import { test, expect } from '@playwright/test';

test('dismissing confirm keeps the member', async ({ page }) => {
  await page.goto('/dialogs');
  page.once('dialog', async (dialog) => {
    expect(dialog.message()).toBe('Delete Ben?');
    await dialog.dismiss();
  });
  await page.getByRole('button', { name: 'Delete Ben' }).click();
  await expect(page.getByRole('status')).toHaveText('Kept Ben');
});

test('modal can be cancelled', async ({ page }) => {
  await page.goto('/dialogs');
  await page.getByRole('button', { name: 'Open settings' }).click();
  const dialog = page.getByRole('dialog', { name: 'Settings' });
  await expect(dialog).toBeVisible();
  await dialog.getByRole('button', { name: 'Cancel' }).click();
  await expect(dialog).toBeHidden();
});
